def _parse_presentation_sync_ndjson(
    ndjson: str, after: int, snapshot: int
) -> Optional[List[Dict[str, Any]]]:
    """解析演示消费历史同步页 NDJSON：合法返回事件行列表，非法
    返回 None。

    规则逐字节沿用外部演示消费历史 export：每行恰为以 LF 结行的
    UTF-8 紧凑 JSON（末行亦有 LF、无 CR、无 BOM、无空行），行对
    象恰含且按键序为 cursor、consumption_id、issuer_did、
    presentation_id、consumed_at；cursor 为非布尔非负整数，其余
    四字段为非空字符串；行内 cursor 严格递增且满足
    after < cursor <= snapshot；页内 (issuer_did, presentation_id)
    不得重复。空串为零行的合法页。
    """
    if not ndjson:
        return []
    if not ndjson.endswith("\n") or "\r" in ndjson:
        return None
    events: List[Dict[str, Any]] = []
    seen_keys: set = set()
    prev_cursor = after
    for line in ndjson.split("\n")[:-1]:
        if not line:
            return None
        try:
            row = json.loads(line)
        except (json.JSONDecodeError, ValueError):
            return None
        if not isinstance(row, dict):
            return None
        if list(row.keys()) != [
            "cursor",
            "consumption_id",
            "issuer_did",
            "presentation_id",
            "consumed_at",
        ]:
            return None
        cursor = row["cursor"]
        if (
            not isinstance(cursor, int)
            or isinstance(cursor, bool)
            or cursor <= after
            or cursor > snapshot
            or cursor <= prev_cursor
        ):
            return None
        for field in (
            "consumption_id",
            "issuer_did",
            "presentation_id",
            "consumed_at",
        ):
            if not isinstance(row[field], str) or not row[field]:
                return None
        key = (row["issuer_did"], row["presentation_id"])
        if key in seen_keys:
            return None
        seen_keys.add(key)
        prev_cursor = cursor
        events.append(row)
    return events

